    // C# program to demonstrate
// LOOK Disk Scheduling algorithm
using System;
using System.Collections.Generic;

class GFG{

static int size = 8; 

static void LOOK(int[] arr, int head, 
                 string direction) 
{ 
    int seek_count = 0; 
    int distance, cur_track; 

    List<int> left = new List<int>(); 
    List<int> right = new List<int>(); 
    List<int> seek_sequence = new List<int>(); 

    // Appending values which are 
    // currently at left and right 
    // direction from the head. 
    for(int i = 0; i < size; i++)
    {
        if (arr[i] < head) 
            left.Add(arr[i]); 
        if (arr[i] > head) 
            right.Add(arr[i]); 
    } 

    // Sorting left and right vectors 
    // for servicing tracks in the 
    // correct sequence. 
    left.Sort();  
    right.Sort();  

    // Run the while loop two times. 
    // one by one scanning right 
    // and left side of the head 
    int run = 2; 
    while (run-- > 0)
    { 
        if (direction == "left") 
        { 
            for(int i = left.Count - 1; i >= 0; i--)
            { 
                cur_track = left[i]; 

                // Appending current track to
                // seek sequence 
                seek_sequence.Add(cur_track); 

                // Calculate absolute distance 
                distance = Math.Abs(cur_track - head); 

                // Increase the total count 
                seek_count += distance; 

                // Accessed track is now the new head 
                head = cur_track; 
            } 

            // Reversing the direction 
            direction = "right"; 
        } 
        else if (direction == "right")
        { 
            for(int i = 0; i < right.Count; i++)
            {
                cur_track = right[i]; 

                // Appending current track to 
                // seek sequence 
                seek_sequence.Add(cur_track); 

                // Calculate absolute distance 
                distance = Math.Abs(cur_track - head); 

                // Increase the total count 
                seek_count += distance; 

                // Accessed track is now new head 
                head = cur_track; 
            } 

            // Reversing the direction 
            direction = "left"; 
        } 
    } 

    Console.WriteLine("Total number of seek " +
                       "operations = " + seek_count);

    Console.WriteLine("Seek Sequence is"); 

    for(int i = 0; i < seek_sequence.Count; i++)
    {
        Console.WriteLine(seek_sequence[i]);
    } 
} 

// Driver code
static void Main() 
{

    // Request array 
    int[] arr = { 176, 79, 34, 60,
                  92, 11, 41, 114 }; 
    int head = 50; 
    string direction = "right"; 

    Console.WriteLine("Initial position of head: " + 
                       head); 

    LOOK(arr, head, direction); 
}
}

